static void grabberLinkRecoveryChecks(const fs::path& root){
 for(int scenario=0;scenario<7;++scenario){
  auto folder=root/L"link-recovery"/wide(std::to_string(scenario)),state=folder/L"state",target=folder/L"page.html";Json before,after;std::string id,oldHash,newHash;auto token=guid();
  {Manager manager(state);manager.state["Queues"][0]["Enabled"]=false;auto job=manager.add("https://example.test/page",utf8(folder.wstring()),"page.html","Main queue",true);writeBytes(target,Bytes{'o','l','d'});job->data["Status"]="Complete";job->data["Size"]=3;job->data["Received"]=3;job->data["ProjectId"]=guid();job->data["Sha256"]=fileHash(target);before=job->data;id=job->id();oldHash=str(before,"Sha256");manager.stop();}
  auto backup=folder/(L".udm-links-"+wide(id)+L"-"+wide(token)+L".before"),pending=folder/(L".udm-links-"+wide(id)+L"-"+wide(token)+L".after"),journal=state/L"link-conversions"/(wide(id)+L".json");
  writeBytes(pending,Bytes{'n','e','w','!'});newHash=fileHash(pending);after=before;after["Sha256"]=newHash;after["GrabberConvertedHash"]=newHash;after["GrabberSourceHash"]=oldHash;after["GrabberSourceBytes"]=3;after["Size"]=4;after["Received"]=4;after["GrabberLinksConvertedAt"]=date();
  if(scenario!=1){fs::rename(target,backup);if(scenario!=2)fs::rename(pending,target);}
  if(scenario==3)after["Folder"]=utf8((folder/L"elsewhere").wstring());
  if(scenario==4)writeBytes(target,Bytes{'e','d','i','t'});
  if(scenario==5){auto catalog=Json::parse(readText(state/L"state.json"));catalog["Downloads"][0]=after;atomicText(state/L"state.json",catalog.dump(),false);fs::remove(backup);}
  if(scenario==6)after["Size"]=9;
  Json operation={{"Version",1},{"Id",id},{"Token",token},{"Target",utf8(target.wstring())},{"OldHash",oldHash},{"NewHash",newHash},{"Before",before},{"After",after}};atomicText(journal,operation.dump(),false);
  if(scenario==3||scenario==4||scenario==6){auto hash=fileHash(target);rejects([&]{Manager recovered(state);},scenario==4?"Recovery refuses to replace a page edited after interruption":"Recovery rejects inconsistent file paths or sizes");check(fileHash(target)==hash&&fs::exists(journal)&&fs::exists(backup),"Rejected recovery preserves the document, backup and journal");}
  else{Manager recovered(state);auto expected=(scenario==0||scenario==5)?newHash:oldHash;check(fileHash(target)==expected&&str(recovered.jobs[0]->data,"Sha256")==expected,"Interrupted conversion recovers a matching document and catalog");check(!fs::exists(journal)&&!fs::exists(pending)&&!fs::exists(backup),"Successful conversion recovery cleans only its verified temporary files");recovered.stop();}
 }
}
