 check(grabberLocalReference(L"C:/mirror/index.html",L"//server/share/a b.png")=="file://server/share/a%20b.png","Network-share destinations use correctly formed file URLs");
 std::map<std::string,std::string> files={{"https://example.test/docs/next.php","next.php.html"},{"https://example.test/img/a.png","../Images/a%20(1).png"},{"https://example.test/js/app.js","../js/app.js"},{"https://example.test/css/base.css","../css/base.css"}};
 const std::string page="<head><base href='/docs/'><script src='/js/app.js'></script><script>let markup='<img src=fake.png>';</script></head><a href='next.php#part'>Next</a><img src='../img/a.png'><img src='/missing.png'><a href='/remote?x=1&amp;y=2#part'>Remote</a>";
 auto converted=rewriteGrabberDocument(page,"https://example.test/start",false,files);
